import { NextResponse } from "next/server";
import Stripe from "stripe";

// Initialize Stripe (Server-Side)
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
    apiVersion: "2025-01-27.acacia", // Use latest API version or default
});

export async function POST(req: Request) {
    try {
        const { items, customerDetails } = await req.json();

        if (!items || items.length === 0) {
            return NextResponse.json({ error: "No items in cart" }, { status: 400 });
        }

        // Create Checkout Session
        const session = await stripe.checkout.sessions.create({
            payment_method_types: ["card"],
            line_items: items.map((item: any) => ({
                price_data: {
                    currency: "usd",
                    product_data: {
                        name: item.name,
                        images: [item.image.startsWith("/") ? `${req.headers.get("origin")}${item.image}` : item.image],
                        // Note: Images need absolute URLs for Stripe
                    },
                    unit_amount: Math.round(item.price * 100),
                },
                quantity: item.quantity,
            })),
            mode: "payment",
            customer_email: customerDetails?.email, // Pre-fill email if passed
            success_url: `${req.headers.get("origin")}/success?session_id={CHECKOUT_SESSION_ID}`,
            cancel_url: `${req.headers.get("origin")}/cart`,
            metadata: {
                shipping_name: `${customerDetails?.firstName} ${customerDetails?.lastName}`,
                shipping_address: customerDetails?.address,
            }
        });

        return NextResponse.json({ sessionId: session.id });
    } catch (err: any) {
        console.error("Stripe Error:", err);
        return NextResponse.json(
            { error: err.message || "Internal Server Error" },
            { status: 500 }
        );
    }
}

"use client";

import { Navbar } from "@/components/Navbar";
import { Footer } from "@/components/Footer";
import { Button } from "@/components/ui/Button";
import { QuantitySelector } from "@/components/ui/QuantitySelector";
import { useCartStore } from "@/store/cartStore";
import { Trash2, ShoppingCart, ArrowRight } from "lucide-react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { useEffect, useState } from "react";

export default function CartPage() {
    const { items, removeItem, updateQuantity, getCartTotal } = useCartStore();
    const [mounted, setMounted] = useState(false);

    useEffect(() => setMounted(true), []);

    if (!mounted) return null;

    return (
        <div className="min-h-screen bg-canvas text-white">
            <Navbar />

            <main className="pt-32 pb-20 max-w-7xl mx-auto px-6">
                <h1 className="text-4xl font-light mb-12">Your Cart ({items.length})</h1>

                {items.length === 0 ? (
                    <div className="text-center py-20 bg-white/5 rounded-3xl border border-white/10">
                        <ShoppingCart className="w-24 h-24 text-white/20 mx-auto mb-6" />
                        <h2 className="text-3xl text-white mb-4">Your cart is empty</h2>
                        <p className="text-white/50 mb-8">Looks like you haven't added any gear yet.</p>
                        <Link href="/product">
                            <Button>Continue Shopping <ArrowRight size={16} className="ml-2" /></Button>
                        </Link>
                    </div>
                ) : (
                    <div className="grid lg:grid-cols-3 gap-12">
                        {/* Cart Items */}
                        <div className="lg:col-span-2 space-y-6">
                            <AnimatePresence>
                                {items.map((item) => (
                                    <motion.div
                                        key={item.id}
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0, height: 0, marginBottom: 0 }}
                                        className="flex gap-6 p-6 bg-white/5 rounded-2xl border border-white/10 relative overflow-hidden group"
                                    >
                                        <div className="w-24 h-24 bg-black/20 rounded-xl shrink-0 p-2">
                                            <img src={item.image} alt={item.name} className="w-full h-full object-contain" />
                                        </div>

                                        <div className="flex-1">
                                            <div className="flex justify-between items-start mb-2">
                                                <h3 className="text-lg font-medium">{item.name}</h3>
                                                <p className="text-lg font-light">${(item.price * item.quantity).toFixed(2)}</p>
                                            </div>

                                            {item.color && (
                                                <p className="text-sm text-white/50 mb-4 flex items-center gap-2">
                                                    Color: <span className="w-3 h-3 rounded-full inline-block" style={{ backgroundColor: item.color === 'Blue' ? '#5b7bb4' : item.color.toLowerCase() }} /> {item.color}
                                                </p>
                                            )}

                                            <div className="flex items-center justify-between">
                                                <QuantitySelector
                                                    quantity={item.quantity}
                                                    onIncrease={() => updateQuantity(item.id, item.quantity + 1)}
                                                    onDecrease={() => updateQuantity(item.id, Math.max(1, item.quantity - 1))}
                                                    className="scale-90 origin-left"
                                                />
                                                <button
                                                    onClick={() => removeItem(item.id)}
                                                    className="text-white/30 hover:text-red-400 transition-colors p-2"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </div>
                                    </motion.div>
                                ))}
                            </AnimatePresence>
                        </div>

                        {/* Order Summary */}
                        <div className="lg:sticky lg:top-32 h-fit">
                            <div className="bg-white/5 backdrop-blur-xl rounded-2xl border border-white/10 p-8">
                                <h3 className="text-xl font-light mb-6">Order Summary</h3>

                                <div className="space-y-4 text-sm mb-8">
                                    <div className="flex justify-between text-white/70">
                                        <span>Subtotal</span>
                                        <span>${getCartTotal().toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-white/70">
                                        <span>Shipping</span>
                                        <span>$0.00</span>
                                    </div>
                                    <div className="flex justify-between text-white/70">
                                        <span>Tax</span>
                                        <span>Included</span>
                                    </div>
                                    <div className="border-t border-white/10 pt-4 flex justify-between text-lg font-medium text-white">
                                        <span>Total</span>
                                        <span>${getCartTotal().toFixed(2)}</span>
                                    </div>
                                </div>

                                <Link href="/checkout">
                                    <Button size="lg" className="w-full">
                                        Proceed to Checkout
                                    </Button>
                                </Link>

                                <div className="mt-6 flex items-center justify-center gap-2 text-white/40 text-xs">
                                    <span className="flex items-center gap-1"><ShieldCheck size={12} /> Secure Checkout</span>
                                </div>
                            </div>

                        </div>
                    </div>
                )}
            </main>
            <Footer />
        </div>
    );
}

function ShieldCheck(props: any) {
    return (
        <svg
            {...props}
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
        >
            <path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z" />
            <path d="m9 12 2 2 4-4" />
        </svg>
    )
}

"use client";

import { useState } from "react";
import { Navbar } from "@/components/Navbar";
import { Footer } from "@/components/Footer";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { useCartStore } from "@/store/cartStore";
import { loadStripe } from "@stripe/stripe-js";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Check, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

// Schema for shipping form
const shippingSchema = z.object({
    firstName: z.string().min(2, "Required"),
    lastName: z.string().min(2, "Required"),
    email: z.string().email("Invalid email"),
    address: z.string().min(5, "Required"),
    city: z.string().min(2, "Required"),
    zip: z.string().min(4, "Required"),
});

type ShippingFormData = z.infer<typeof shippingSchema>;

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export default function CheckoutPage() {
    const [step, setStep] = useState(1);
    const [loading, setLoading] = useState(false);
    const { items, getCartTotal } = useCartStore();

    const { register, handleSubmit, formState: { errors }, watch } = useForm<ShippingFormData>({
        resolver: zodResolver(shippingSchema),
    });

    const formData = watch();

    const handlePayment = async (data: ShippingFormData) => {
        setLoading(true);
        try {
            const stripe = await stripePromise;
            if (!stripe) throw new Error("Stripe not loaded");

            const response = await fetch("/api/checkout", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    items,
                    customerDetails: data
                }),
            });

            const { sessionId, error } = await response.json();
            if (error) throw new Error(error);

            await stripe.redirectToCheckout({ sessionId });
        } catch (err) {
            console.error(err);
            alert("Checkout failed. Check console.");
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-canvas text-white">
            <Navbar />

            <main className="pt-32 pb-20 max-w-7xl mx-auto px-6">
                <h1 className="text-4xl font-light mb-12">Checkout</h1>

                <div className="grid lg:grid-cols-2 gap-16">

                    {/* Left Column: Flow */}
                    <div>
                        {/* Steps Indicator */}
                        <div className="flex items-center gap-4 mb-12">
                            <div className={cn("flex items-center gap-2", step >= 1 ? "text-blue-400" : "text-white/30")}>
                                <div className="w-8 h-8 rounded-full border-2 border-current flex items-center justify-center font-bold">1</div>
                                <span className="font-medium">Shipping</span>
                            </div>
                            <div className="w-12 h-px bg-white/10" />
                            <div className={cn("flex items-center gap-2", step >= 2 ? "text-blue-400" : "text-white/30")}>
                                <div className="w-8 h-8 rounded-full border-2 border-current flex items-center justify-center font-bold">2</div>
                                <span className="font-medium">Payment</span>
                            </div>
                        </div>

                        {/* Step 1: Shipping Form */}
                        {step === 1 && (
                            <form onSubmit={handleSubmit((d) => setStep(2))} className="space-y-6 animate-in slide-in-from-left-4 fade-in duration-500">
                                <div className="grid grid-cols-2 gap-4">
                                    <Input label="First Name" {...register("firstName")} error={errors.firstName?.message} />
                                    <Input label="Last Name" {...register("lastName")} error={errors.lastName?.message} />
                                </div>
                                <Input label="Email Address" type="email" {...register("email")} error={errors.email?.message} />
                                <Input label="Street Address" {...register("address")} error={errors.address?.message} />
                                <div className="grid grid-cols-2 gap-4">
                                    <Input label="City" {...register("city")} error={errors.city?.message} />
                                    <Input label="ZIP Code" {...register("zip")} error={errors.zip?.message} />
                                </div>

                                <Button type="submit" size="lg" className="w-full mt-6">
                                    Continue to Payment <Check className="ml-2 w-4 h-4" />
                                </Button>
                            </form>
                        )}

                        {/* Step 2: Review & Pay */}
                        {step === 2 && (
                            <div className="space-y-8 animate-in slide-in-from-left-4 fade-in duration-500">
                                <div className="bg-white/5 rounded-xl p-6 border border-white/10">
                                    <div className="flex justify-between items-center mb-4">
                                        <h3 className="font-medium text-white/70">Shipping To</h3>
                                        <button onClick={() => setStep(1)} className="text-blue-400 text-sm hover:underline">Edit</button>
                                    </div>
                                    <p className="text-lg">{formData.firstName} {formData.lastName}</p>
                                    <p className="text-white/60">{formData.address}</p>
                                    <p className="text-white/60">{formData.city}, {formData.zip}</p>
                                </div>

                                <div className="bg-white/5 rounded-xl p-6 border border-white/10">
                                    <h3 className="font-medium text-white/70 mb-4">Payment Method</h3>
                                    <div className="flex items-center gap-2 p-3 bg-black/20 rounded border border-white/5">
                                        <ShieldCheck className="text-green-400" size={18} />
                                        <span className="text-sm">Secure Redirect to Stripe</span>
                                    </div>
                                </div>

                                <Button
                                    onClick={handleSubmit(handlePayment)}
                                    disabled={loading}
                                    size="lg"
                                    className="w-full"
                                >
                                    {loading ? <Loader2 className="animate-spin" /> : `Pay $${getCartTotal().toFixed(2)}`}
                                </Button>
                            </div>
                        )}
                    </div>

                    {/* Right Column: Order Summary (Sticky) */}
                    <div className="lg:sticky lg:top-32 h-fit">
                        <div className="bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 p-8">
                            <h3 className="text-xl font-light mb-6">Your Order</h3>
                            <div className="space-y-4 mb-8">
                                {items.map(item => (
                                    <div key={item.id} className="flex gap-4">
                                        <div className="w-16 h-16 bg-white/5 rounded-lg p-1">
                                            <img src={item.image} className="w-full h-full object-contain" />
                                        </div>
                                        <div className="flex-1">
                                            <p className="font-medium line-clamp-1">{item.name}</p>
                                            <p className="text-sm text-white/50">Qty: {item.quantity}</p>
                                        </div>
                                        <p>${(item.price * item.quantity).toFixed(2)}</p>
                                    </div>
                                ))}
                            </div>
                            <div className="border-t border-white/10 pt-4 flex justify-between text-xl font-medium">
                                <span>Total Today</span>
                                <span>${getCartTotal().toFixed(2)}</span>
                            </div>
                        </div>
                    </div>

                </div>
            </main>
            <Footer />
        </div>
    );
}

function ShieldCheck(props: any) {
    return (
        <svg
            {...props}
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
        >
            <path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z" />
            <path d="m9 12 2 2 4-4" />
        </svg>
    )
}

"use client";

import { useState } from "react";
import { Navbar } from "@/components/Navbar";
import { Footer } from "@/components/Footer";
import { Button } from "@/components/ui/Button";
import { QuantitySelector } from "@/components/ui/QuantitySelector";
import { useCartStore } from "@/store/cartStore";
import { Check, ShieldCheck, Truck, ArrowLeft, Star } from "lucide-react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import { useRouter } from "next/navigation";

export default function ProductPage() {
    const router = useRouter();
    const [selectedColor, setSelectedColor] = useState("Blue");
    const [quantity, setQuantity] = useState(1);
    const [activeTab, setActiveTab] = useState("specs");

    const addItem = useCartStore((state) => state.addItem);

    const colors = [
        { name: "Blue", value: "#5b7bb4" },
        { name: "Gray", value: "#71717a" },
        { name: "Black", value: "#18181b" },
    ];

    const handleAddToCart = () => {
        addItem({
            id: `flexcore-${selectedColor.toLowerCase()}`,
            name: "FlexCore Arc Back Stretcher",
            price: 89.99,
            quantity,
            image: "/sequence/frame_100.webp", // Fallback image
            color: selectedColor,
        });
        // Optional: Toast notification here
    };

    const handleBuyNow = () => {
        handleAddToCart();
        router.push("/checkout");
    }

    return (
        <div className="min-h-screen bg-canvas text-white">
            <Navbar />

            <main className="pt-32 pb-20 max-w-7xl mx-auto px-6">
                <Link href="/" className="inline-flex items-center text-white/50 hover:text-white mb-8 transition-colors">
                    <ArrowLeft size={16} className="mr-2" /> Back to Home
                </Link>

                <div className="grid lg:grid-cols-2 gap-16 mb-24">
                    {/* Left Column: Gallery (Sticky) */}
                    <div className="relative h-fit lg:sticky lg:top-32">
                        <div className="aspect-square bg-white/5 rounded-3xl border border-white/10 flex items-center justify-center p-12 mb-6 overflow-hidden relative group">
                            <div className="absolute inset-0 bg-gradient-radial from-white/5 to-transparent opacity-50" />
                            <motion.img
                                src="/sequence/frame_100.webp" // Use Frame 100 as hero product shot
                                alt="FlexCore Arc"
                                className="w-full h-full object-contain drop-shadow-2xl z-10"
                                initial={{ scale: 0.9, opacity: 0 }}
                                animate={{ scale: 1, opacity: 1 }}
                                transition={{ duration: 0.8 }}
                            />
                        </div>
                        <div className="grid grid-cols-4 gap-4">
                            {[1, 50, 100, 150].map((frame, i) => (
                                <div key={i} className="aspect-square bg-white/5 rounded-xl border border-white/10 hover:border-blue-400/50 transition-colors cursor-pointer p-2">
                                    <img src={`/sequence/frame_${String(frame).padStart(3, '0')}.webp`} className="w-full h-full object-contain opacity-80 hover:opacity-100" />
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Right Column: Details */}
                    <div>
                        <h1 className="text-5xl font-light tracking-tight text-white mb-4">
                            FlexCore Arc Back Stretcher
                        </h1>
                        <p className="text-white/60 text-lg mb-8 font-light">
                            3-Layer Ergonomic Design for Lumbar Relief
                        </p>

                        <div className="flex items-end gap-4 mb-8">
                            <span className="text-4xl font-light text-white">$89.99</span>
                            <span className="text-white/40 line-through text-xl">$129.99</span>
                            <span className="px-3 py-1 bg-blue-500/20 text-blue-300 rounded-full text-sm font-medium">Save $40</span>
                        </div>

                        {/* Color Selection */}
                        <div className="mb-8">
                            <label className="text-white/70 text-sm mb-3 block">Color Accent</label>
                            <div className="flex gap-3">
                                {colors.map((c) => (
                                    <button
                                        key={c.name}
                                        onClick={() => setSelectedColor(c.name)}
                                        className={cn(
                                            "w-12 h-12 rounded-full border-2 transition-all relative",
                                            selectedColor === c.name ? "border-white scale-110" : "border-white/20 hover:border-white/50"
                                        )}
                                        style={{ background: c.value }}
                                        title={c.name}
                                    >
                                        {selectedColor === c.name && (
                                            <span className="absolute inset-0 flex items-center justify-center">
                                                <Check size={16} className="text-white drop-shadow-md" />
                                            </span>
                                        )}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Quantity */}
                        <div className="flex items-center gap-4 mb-10">
                            <label className="text-white/70">Quantity</label>
                            <QuantitySelector
                                quantity={quantity}
                                onIncrease={() => setQuantity(q => q + 1)}
                                onDecrease={() => setQuantity(q => Math.max(1, q - 1))}
                            />
                        </div>

                        {/* CTAs */}
                        <div className="flex flex-col gap-4 mb-10">
                            <Button onClick={handleAddToCart} size="lg" className="w-full py-5 text-lg">
                                Add to Cart — ${(89.99 * quantity).toFixed(2)}
                            </Button>
                            <Button onClick={handleBuyNow} variant="outline" size="lg" className="w-full py-5 text-lg">
                                Buy Now (Express Checkout)
                            </Button>
                        </div>

                        {/* Trust Signals */}
                        <div className="space-y-3 text-sm text-white/60 pt-8 border-t border-white/10">
                            <div className="flex items-center gap-3">
                                <Truck size={18} className="text-blue-400" /> Free shipping on orders over $50
                            </div>
                            <div className="flex items-center gap-3">
                                <ShieldCheck size={18} className="text-blue-400" /> 30-day money-back guarantee
                            </div>
                            <div className="flex items-center gap-3">
                                <Check size={18} className="text-blue-400" /> Ships within 2-3 business days
                            </div>
                        </div>
                    </div>
                </div>

                {/* Tabbed Content */}
                <div className="max-w-4xl mx-auto">
                    <div className="flex border-b border-white/10 mb-8">
                        {['specs', 'how-it-works', 'reviews'].map((tab) => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab)}
                                className={cn(
                                    "px-8 py-4 text-sm font-medium transition-colors relative",
                                    activeTab === tab ? "text-white" : "text-white/40 hover:text-white/70"
                                )}
                            >
                                {tab === 'specs' && 'Specifications'}
                                {tab === 'how-it-works' && 'How It Works'}
                                {tab === 'reviews' && 'Reviews (2.8k)'}
                                {activeTab === tab && (
                                    <motion.div layoutId="activeTab" className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-500" />
                                )}
                            </button>
                        ))}
                    </div>

                    <div className="bg-white/5 rounded-2xl p-8 border border-white/10 min-h-[300px]">
                        {activeTab === 'specs' && (
                            <div className="grid md:grid-cols-2 gap-8">
                                <div>
                                    <h3 className="text-xl text-white mb-4">Technical Details</h3>
                                    <ul className="space-y-4 text-white/70">
                                        <li className="flex justify-between border-b border-white/5 pb-2"><span>Dimensions</span> <span>15" × 10" × 4"</span></li>
                                        <li className="flex justify-between border-b border-white/5 pb-2"><span>Weight</span> <span>2.1 lbs</span></li>
                                        <li className="flex justify-between border-b border-white/5 pb-2"><span>Material</span> <span>Medical-grade TPE, ABS</span></li>
                                        <li className="flex justify-between border-b border-white/5 pb-2"><span>Load Capacity</span> <span>350 lbs</span></li>
                                    </ul>
                                </div>
                                <div>
                                    <h3 className="text-xl text-white mb-4">In The Box</h3>
                                    <ul className="list-disc pl-5 space-y-2 text-white/70">
                                        <li>FlexCore Arc Base Unit</li>
                                        <li>Memory Foam Comfort Strip</li>
                                        <li>User Guide & Exercise Chart</li>
                                        <li>Travel Bag</li>
                                    </ul>
                                </div>
                            </div>
                        )}
                        {activeTab === 'reviews' && (
                            <div className="text-center py-10">
                                <div className="flex items-center justify-center gap-1 text-yellow-400 mb-4">
                                    {[1, 2, 3, 4, 5].map(i => <Star key={i} fill="currentColor" />)}
                                </div>
                                <h3 className="text-2xl text-white mb-2">4.8 out of 5 Stars</h3>
                                <p className="text-white/50 mb-6">Based on 2,847 verified reviews</p>
                                <Link href="/reviews">
                                    <Button variant="secondary">View All Reviews</Button>
                                </Link>
                            </div>
                        )}
                        {activeTab === 'how-it-works' && (
                            <div className="grid md:grid-cols-3 gap-8 text-center">
                                {[1, 2, 3].map((step) => (
                                    <div key={step} className="bg-white/5 p-6 rounded-xl">
                                        <div className="w-12 h-12 bg-blue-500/20 text-blue-400 rounded-full flex items-center justify-center mx-auto mb-4 font-bold text-xl">
                                            {step}
                                        </div>
