import { useScroll, useTransform, motion } from "framer-motion";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

const FRAME_COUNT = 192;

export default function ChipScroll() {
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [images, setImages] = useState<HTMLImageElement[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const { scrollYProgress } = useScroll({
        target: containerRef,
        offset: ["start start", "end end"],
    });

    const frameIndex = useTransform(scrollYProgress, [0, 1], [0, FRAME_COUNT - 1]);

    useEffect(() => {
        // Preload images
        const loadImages = async () => {
            const loadedImages: HTMLImageElement[] = [];

            // Create a promise for each image load
            const imagePromises = Array.from({ length: FRAME_COUNT }, (_, i) => {
                return new Promise<void>((resolve) => {
                    const img = new Image();
                    const frameNum = String(i + 1).padStart(3, "0");
                    img.src = `/sequence/frame_${frameNum}.webp`;
                    img.onload = () => {
                        loadedImages[i] = img;
                        resolve();
                    };
                    img.onerror = () => {
                        // Fallback or just resolve to avoid hanging
                        console.warn(`Failed to load frame ${i + 1}`);
                        resolve();
                    };
                });
            });

            await Promise.all(imagePromises);
            setImages(loadedImages);
            setIsLoading(false);
        };

        loadImages();
    }, []);

    useEffect(() => {
        // Render loop
        const render = () => {
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext("2d");
            if (!canvas || !ctx || images.length === 0) return;

            // Handle high DPI
            const dpr = window.devicePixelRatio || 1;
            // Set internal dimensions if changed
            if (canvas.width !== canvas.clientWidth * dpr || canvas.height !== canvas.clientHeight * dpr) {
                canvas.width = canvas.clientWidth * dpr;
                canvas.height = canvas.clientHeight * dpr;
                ctx.scale(dpr, dpr);
            }

            const currentIndex = Math.min(
                FRAME_COUNT - 1,
                Math.max(0, Math.round(frameIndex.get()))
            );
            const img = images[currentIndex];

            if (img) {
                // Clear canvas
                ctx.clearRect(0, 0, canvas.width, canvas.height); // Note: width/height here are physical pixels

                // Draw image 'contain' style
                // Since context is scaled, we think in CSS pixels
                const canvasWidth = canvas.clientWidth;
                const canvasHeight = canvas.clientHeight;

                const imgAspect = img.width / img.height;
                const canvasAspect = canvasWidth / canvasHeight;

                let drawWidth, drawHeight, offsetX, offsetY;

                if (canvasAspect > imgAspect) {
                    drawHeight = canvasHeight;
                    drawWidth = canvasHeight * imgAspect;
                    offsetX = (canvasWidth - drawWidth) / 2;
                    offsetY = 0;
                } else {
                    drawWidth = canvasWidth;
                    drawHeight = canvasWidth / imgAspect;
                    offsetX = 0;
                    offsetY = (canvasHeight - drawHeight) / 2;
                }

                ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
            }

            requestAnimationFrame(render);
        };

        const animationId = requestAnimationFrame(render);
        return () => cancelAnimationFrame(animationId);
    }, [images, frameIndex]);

    return (
        <div ref={containerRef} className="relative h-[800vh] w-full bg-canvas">
            {/* Loading State */}
            {isLoading && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-canvas">
                    <div className="flex flex-col items-center gap-4">
                        <motion.div
                            animate={{ rotate: 360 }}
                            transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
                            className="h-12 w-12 rounded-full border-2 border-white/20 border-t-white"
                        />
                        <p className="text-sm font-light tracking-widest text-white/50 uppercase">Loading Experience</p>
                    </div>
                </div>
            )}

            <div className="sticky top-0 h-screen w-full overflow-hidden">
                <canvas
                    ref={canvasRef}
                    className="h-full w-full object-cover"
                />
                {/* Vignette Overlay */}
                <div className="pointer-events-none absolute inset-0 bg-gradient-radial from-transparent via-[#454447]/10 to-[#454447]/80" />
            </div>

            {/* Scroll Triggers / Text Sections would be placed relative to this container in parent, or passed as children */}
        </div>
    );
}

